import re

path = 'src/game/HoleRuntime.ts'
source = open(path, encoding='utf-8').read()

R1 = """import { ZoneManager } from '../gameplay/zones/ZoneManager';
import {
  createForceObstacle,
  createPad,
  createZone,
  isFieldObstacle,
  isForceObstacle,
  isHazardObstacle,
  isPadDescriptor,
} from '../obstacles/descriptors';
import { sampleMover } from '../obstacles/movers';
import type { MoverConfig, MoverKind } from '../obstacles/movers';
import type { PadObstacle } from '../obstacles/pads';
import { rotationAngle } from '../obstacles/rotating';
import type { RotatingConfig, RotatingKind } from '../obstacles/rotating';
"""

R2 = """/** Platforms, sliding walls and doors travelling along a straight track. */
interface TranslateMover extends MoverBase {
  motion: 'translate';
  config: MoverConfig;
}

type Mover = SpinMover | TranslateMover;

/** What the sensor volumes want done to the ball after one fixed step. */
export interface BallEffect {
  /** Velocity to write back; equal to the sampled one when nothing acted. */
  velocity: Vec3;
  /** Set when a teleporter moved the ball. */
  position?: Vec3;
  clearAngularVelocity?: boolean;
  /** False when no volume touched the ball, so callers can skip the write. */
  changed: boolean;
  /** Ids of the volumes that acted, in the order they were applied. */
  sources: string[];
}

export interface HazardResolution {
  resetPosition: Vec3;
  penaltyStrokes: number;
}
"""

R3 = """  /** Rigid bodies this hole owns; volumes add none, which is what keeps them passable. */
  get bodyCount(): number {
    return this.bodies.length;
  }

  /** Hazards, force obstacles, pads and fields that act through sensors instead of colliders. */
  get sensorCount(): number {
    return this.hazards.length + this.forces.length + this.pads.length + this.fields.length;
  }

  /** Live pose of a moving obstacle, read back from its kinematic body. */
  moverPose(id: string): { position: Vec3; rotation: { x: number; y: number; z: number; w: number } } | undefined {
    const mover = this.movers.find((candidate) => candidate.id === id);
    if (!mover) return undefined;
    const translation = mover.body.translation();
    const rotation = mover.body.rotation();
    return {
      position: { x: translation.x, y: translation.y, z: translation.z },
      rotation: { x: rotation.x, y: rotation.y, z: rotation.z, w: rotation.w },
    };
"""

R4 = """  /** Turns a part around its axis and, for swings, carries it along the arc. */
  private updateSpin(mover: SpinMover): void {
    this.tmpSpin.setFromAxisAngle(mover.axis, rotationAngle(mover.config, this.elapsed));
    this.tmpQuaternion.copy(this.tmpSpin).multiply(mover.baseRotation);
    mover.body.setNextKinematicRotation({
      x: this.tmpQuaternion.x,
      y: this.tmpQuaternion.y,
      z: this.tmpQuaternion.z,
      w: this.tmpQuaternion.w,
    });
    mover.object?.quaternion.copy(this.tmpQuaternion);

    if (!mover.pivot) return;
    this.tmpVector.copy(mover.arm).applyQuaternion(this.tmpSpin).add(mover.pivot);
    mover.body.setNextKinematicTranslation({ x: this.tmpVector.x, y: this.tmpVector.y, z: this.tmpVector.z });
    mover.object?.position.copy(this.tmpVector);
  }

  /** Slides a part along its track; sampleMover owns ping-pong, loop, once and the end pauses. */
  private updateTranslate(mover: TranslateMover): void {
    const sample = sampleMover(mover.config, this.elapsed);
    mover.body.setNextKinematicTranslation(sample.position);
    mover.object?.position.set(sample.position.x, sample.position.y, sample.position.z);
  }

  /**
   * One fixed step of the sensor volumes: force obstacles first (belts, fans and
   * teleporters), then the impulse pads, then the force fields. The caller writes the
   * resulting velocity - and the teleport target, when one fired - back onto the body.
   */
  applyBallEffects(sample: BallSample, dt: number, mass: number): BallEffect {
    const effect: BallEffect = { velocity: { ...sample.velocity }, changed: false, sources: [] };
    if (dt <= 0) return effect;
    const context = { dt, elapsed: this.elapsed };
    let position: Vec3 = { ...sample.position };

    for (const force of this.forces) {
      const result = force.update({ position, velocity: effect.velocity, radius: sample.radius }, context);
      if (!result) continue;
      effect.sources.push(result.obstacleId);
      effect.changed = true;
      if (result.teleport) {
        position = { ...result.teleport.position };
        effect.position = { ...result.teleport.position };
        effect.velocity = { ...result.teleport.velocity };
        effect.clearAngularVelocity = result.teleport.clearAngularVelocity;
        continue;
      }
      if (result.deltaVelocity) effect.velocity = addVec3(effect.velocity, result.deltaVelocity);
    }

    if (Math.hypot(effect.velocity.x, effect.velocity.z) >= PAD_TRIGGER_SPEED) {
      for (const pad of this.pads) {
        const hit = pad.update(position, effect.velocity, this.elapsed);
        if (!hit) continue;
        effect.velocity = hit.velocity;
        effect.changed = true;
        effect.sources.push(hit.padId);
      }
    }

    if (mass > 0 && this.fields.length > 0) {
      const field = this.fieldManager.calculateForces(position, effect.velocity, mass);
      const acceleration = cappedVelocity(scaleVec3(field, 1 / mass), MAX_FIELD_ACCELERATION);
      if (acceleration.x !== 0 || acceleration.y !== 0 || acceleration.z !== 0) {
        effect.velocity = addVec3(effect.velocity, scaleVec3(acceleration, dt));
        effect.changed = true;
      }
    }

    return effect;
  }

  /** Clears teleporter latches and pad cooldowns; call it whenever a turn or ball restarts. */
  resetObstacles(): void {
    for (const force of this.forces) force.reset();
    for (const pad of this.pads) pad.reset();
"""

replacements = iter([R1, R2, R3, R4])
pattern = re.compile(r'<<<<<<< HEAD\n.*?\n=======\n.*?\n>>>>>>> [0-9a-f]{40}\n', re.S)
resolved, count = pattern.subn(lambda match: next(replacements), source)
assert count == 4, count
assert '<<<<<<<' not in resolved and '>>>>>>>' not in resolved
open(path, 'w', encoding='utf-8').write(resolved)
print('resolved regions:', count)
PY
